&lt;p style=&quot;margin: 0in; font-family: &#39;Times New Roman&#39;; font-size: 12.0pt;&quot;&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif; font-size: 12pt;&quot;&gt;Pet insurance&lt;/span&gt;&lt;/p&gt;
&lt;p style=&quot;margin: 0in; font-family: &#39;Times New Roman&#39;; font-size: 12.0pt;&quot;&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif; font-size: 12pt;&quot;&gt;Tuition and continuing education reimbursement&lt;/span&gt;&lt;/p&gt;
&lt;p style=&quot;margin: 0in; font-family: &#39;Times New Roman&#39;; font-size: 12.0pt;&quot;&gt;&amp;nbsp;&lt;/p&gt;
